mapper.sql:
w.tenant_id = #{tenantId}
AND w.is_deleted = 0
AND w.work_type = #{workType}
AND w.status_node_id = #{statusNodeId}
AND w.assignee_type = #{assigneeType}
AND w.assignee_ref = #{assigneeRef}

    AND w.assignee_type = 'HUMAN'
    AND w.assignee_ref = #{currentUserId}
    AND EXISTS (
        SELECT 1 FROM dispatch d
        WHERE d.id = (
            SELECT MAX(d2.id) FROM dispatch d2
            WHERE d2.tenant_id = w.tenant_id
              AND d2.workitem_id = w.id
              AND d2.is_deleted = 0
        )
          AND d.status = 'SUCCEEDED'
          AND d.is_deleted = 0
    )
    AND NOT EXISTS (
        SELECT 1 FROM status_node sn
        WHERE sn.id = w.status_node_id
          AND (
              UPPER(COALESCE(sn.category, '')) = 'DONE'
              OR UPPER(COALESCE(sn.code, '')) LIKE '%DONE%'
              OR UPPER(COALESCE(sn.code, '')) LIKE '%CLOSED%'
              OR UPPER(COALESCE(sn.code, '')) LIKE '%RELEASED%'
              OR COALESCE(sn.name, '') LIKE '%完成%'
              OR COALESCE(sn.name, '') LIKE '%关闭%'
              OR COALESCE(sn.name, '') LIKE '%发布%'
              OR UPPER(COALESCE(sn.name, '')) LIKE '%DONE%'
              OR UPPER(COALESCE(sn.name, '')) LIKE '%CLOSED%'
              OR UPPER(COALESCE(sn.name, '')) LIKE '%RELEASED%'
          )
    )

AND w.creator_id = #{currentUserId}
AND w.assignee_type = 'HUMAN' AND w.assignee_ref = #{currentUserId}

    AND (w.title LIKE CONCAT('%', #{keyword}, '%')
    OR w.id = #{keywordId})

mapper.update:
UPDATE workitem SET title = #{title}, content_md = #{contentMd},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET is_deleted = 1,
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET status_node_id = #{statusNodeId},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET template_id = #{templateId}, status_node_id = #{statusNodeId},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET assignee_type = #{assigneeType}, assignee_ref = #{assigneeRef},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

UPDATE workitem SET assign_operator_id = #{assignOperatorId},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

mapper.select:
SELECT COUNT(*) FROM workitem w
INNER JOIN status_node sn ON sn.id = w.status_node_id
WHERE w.is_deleted = 0
  AND w.assignee_type = #{assigneeType}
  AND w.assignee_ref = #{assigneeRef}
  AND sn.category NOT IN ('DONE', 'CANCELED')

mapper.update:
UPDATE workitem
SET current_step_id = #{currentStepId},
    version = version + 1,
    modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId}
  AND version = #{version} AND is_deleted = 0

